using Greyhaven.Content;
using Greyhaven.Server;
using System.Text.Json;
var root=Path.GetFullPath(args[0]);using var p=new ContentPackage(root);var world=new OriginalWorld(p);string baseline=Wire.Encode(world.State);int count=0;
void Assert(bool ok,string message="Assertion failed"){if(!ok)throw new Exception(message);}
void Test(string name,Action body){world.Restore(new(){Fingerprint=p.Fingerprint,MapHash=p.MapHash,Map=p.Map.Clone(),State=JsonSerializer.Deserialize<SessionState>(baseline,ContentPackage.Json)!});world.State.Paused=false;body();AdventureRules.Validate(p,world.State);InventoryRules.Validate(p,world.State);CombatRules.Validate(p,world.State);count++;Console.WriteLine("PASS "+name);}
void At(int x,int y){world.State.X=x;world.State.Y=y;world.State.Z=p.Map.Get(x,y).Z;}
void Npc(string id){var o=p.Map.Objects.First(o=>o.Id==id);var at=AdventureRules.Position(world.State,o);At(at.x,at.y);}
Reply Call(string type,string target="",string item="",string destination="",int amount=0)=>world.Handle(new(){Type=type,TargetId=target,ItemId=item,Destination=destination,Amount=amount});
void Good(string type,string target="",string item="",string destination="",int amount=0){var r=Call(type,target,item,destination,amount);Assert(r.Ok,r.Message);}
void Bad(string type,string target="",string item="",string destination="",int amount=0){string before=Wire.Encode(world.State);var r=Call(type,target,item,destination,amount);Assert(!r.Ok,"Expected rejected "+type);Assert(before==Wire.Encode(world.State),"Rejected action mutated state: "+r.Message);}
QuestProgress Q(string id)=>world.State.Adventure.Quests.First(q=>q.Id==id);
void Tick(double seconds){for(double t=0;t<seconds;t+=.1)world.Advance(Math.Min(.1,seconds-t));}
void ReadyMain(){var d=p.AdventureCatalog.Quests.First(d=>d.Main);var q=Q(d.Id);q.Status="ready";q.Counts=d.Objectives.Select(o=>o.Amount).ToList();world.State.Adventure.BeaconRestored=true;Npc("npc.sera");}
Test("main quest, three side quests, eleven capped skills and fifteen residents initialize",()=>Assert(world.State.Adventure.Enabled&&world.State.Adventure.Quests.Count==4&&world.State.Adventure.Skills.Count==11&&world.State.Adventure.Npcs.Count==15));
Test("acceptance requires nearby giver and is never automatic",()=>{Assert(Q("quest.beacon").Status=="available");Bad("quest-accept","quest.beacon");Npc("npc.sera");Good("quest-accept","quest.beacon");Assert(Q("quest.beacon").Status=="active");Bad("quest-accept","quest.beacon");Bad("quest-claim","quest.beacon");});
Test("supply quest requires explicit marks and consumes exactly the requested quantity",()=>{Npc("npc.orrin");Good("quest-accept","quest.forge");var crystal=world.State.Items.First(i=>i.Definition.EndsWith("tide-crystal"));int total=world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal")).Sum(i=>i.Amount);Assert(Q("quest.forge").Status=="active","accept: "+Wire.Encode(Q("quest.forge")));Good("quest-mark","quest.forge",crystal.Id);Assert(Q("quest.forge").Status=="ready","marked: "+Wire.Encode(Q("quest.forge")));Good("quest-claim","quest.forge");Assert(Q("quest.forge").Status=="claimed","claim: "+Wire.Encode(Q("quest.forge")));Assert(world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal")).Sum(i=>i.Amount)==total-3,"quantity after claim: before="+total+" after="+world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal")).Sum(i=>i.Amount)+" items="+Wire.Encode(world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal"))));Assert(world.State.Items.All(i=>i.QuestId!="quest.forge"),"flags after claim");Bad("quest-claim","quest.forge");});
Test("quest marks prevent sale, ground drops and ordinary stack merges",()=>{Npc("npc.orrin");Good("quest-accept","quest.forge");var crystal=world.State.Items.First(i=>i.Definition.EndsWith("tide-crystal"));Good("quest-mark","quest.forge",crystal.Id);Npc("npc.nessa");Bad("trade","",crystal.Id,"sell",1);string before=Wire.Encode(world.State);var r=world.Handle(new(){Type="transfer",ItemId=crystal.Id,Destination="ground",X=world.State.X,Y=world.State.Y,Amount=1});Assert(!r.Ok&&Wire.Encode(world.State)==before);});
Test("marked stack splits keep their quest identity",()=>{Npc("npc.orrin");Good("quest-accept","quest.forge");var crystal=world.State.Items.First(i=>i.Definition.EndsWith("tide-crystal"));Good("quest-mark","quest.forge",crystal.Id);var r=world.Handle(new(){Type="transfer",ItemId=crystal.Id,Destination="bag",X=50,Y=280,Amount=1});Assert(r.Ok&&world.State.Items.Where(i=>i.Definition==crystal.Definition&&InventoryRules.Carried(world.State,i)).All(i=>i.QuestId=="quest.forge"));});
Test("abandoning a supply quest releases marks without losing units",()=>{Npc("npc.orrin");Good("quest-accept","quest.forge");Good("quest-mark","quest.forge");int qty=world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal")).Sum(i=>i.Amount);Good("quest-abandon","quest.forge");Assert(Q("quest.forge").Status=="available"&&world.State.Items.All(i=>i.QuestId!="quest.forge")&&world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal")).Sum(i=>i.Amount)==qty);});
Test("delivery quest issues one physical letter and requires the recipient",()=>{Npc("npc.mara");Good("quest-accept","quest.harbour");Assert(world.State.Items.Single(i=>i.Id==AdventureRules.Mail).QuestId=="quest.harbour");Bad("quest-claim","quest.harbour");Npc("npc.cora");Good("interact","npc.cora");Assert(Q("quest.harbour").Status=="ready");Good("quest-claim","quest.harbour");Assert(!world.State.Items.Any(i=>i.Id==AdventureRules.Mail)&&Q("quest.harbour").Status=="claimed");});
Test("delivery abandonment and reacceptance do not duplicate letters",()=>{Npc("npc.mara");Good("quest-accept","quest.harbour");Good("quest-abandon","quest.harbour");Assert(!world.State.Items.Any(i=>i.Id==AdventureRules.Mail));Good("quest-accept","quest.harbour");Assert(world.State.Items.Count(i=>i.Id==AdventureRules.Mail)==1);});
Test("finite previously defeated road encounters count without respawning",()=>{foreach(var e in world.State.Combat.Enemies.Where(e=>e.Id is "encounter.woods.hound1" or "encounter.woods.hound2")){e.Health=0;e.Behavior="Dead";e.LootSpawned=true;}Npc("npc.lena");Good("quest-accept","quest.morrowwood");Assert(Q("quest.morrowwood").Status=="ready");Good("quest-claim","quest.morrowwood");});
Test("full beacon objective and reward chain preserves identity and prevents replay",()=>{Npc("npc.sera");Good("quest-accept","quest.beacon");Npc("npc.orrin");Good("interact","npc.orrin");At(88,52);WorldSimulation.Enter(p,world.State);At(89,46);Good("interact","stairs.beacon");var step=world.Handle(new(){Type="step",Dx=0,Dy=-1});Assert(step.Ok,step.Message);At(215,28);var key=world.Handle(new(){Type="transfer",ItemId="world.item.cellar.key",Destination="bag",X=60,Y=280});Assert(key.Ok,key.Message);At(226,120);Good("interact","cellar.lever");var boss=world.State.Combat.Enemies.First(e=>e.Id=="encounter.lower.boss");boss.Health=1;At(238,120);AdventureRules.Skill(world.State,"magery").Value=1000;Good("cast",boss.Id,"greyhaven.spell.ember");Tick(1.4);Assert(boss.Health==0||world.State.Combat.Enemies.First(e=>e.Id==boss.Id).Health==0);var heart=world.State.Items.Single(i=>i.Id==AdventureRules.Heart);Assert(heart.QuestId=="quest.beacon");var pickup=world.Handle(new(){Type="transfer",ItemId=heart.Id,Destination="bag",X=165,Y=250});Assert(pickup.Ok,pickup.Message);At(89,46);Good("restore-beacon");Assert(world.State.Adventure.BeaconRestored&&!world.State.Items.Any(i=>i.Id==AdventureRules.Heart));Npc("npc.sera");Assert(Q("quest.beacon").Status=="ready",Wire.Encode(Q("quest.beacon")));Good("quest-claim","quest.beacon");Assert(Q("quest.beacon").Status=="claimed"&&world.State.Items.Any(i=>i.Definition.EndsWith("greatblade"))&&AdventureRules.Title(world.State)=="Lantern Warden");Bad("quest-claim","quest.beacon");Bad("restore-beacon");});
Test("boss heart creation is stable and finite, including late quest acceptance",()=>{var boss=world.State.Combat.Enemies.First(e=>e.Id=="encounter.lower.boss");boss.Health=0;boss.Behavior="Dead";boss.LootSpawned=true;AdventureSimulation.EnsureHeart(p,world.State);AdventureSimulation.EnsureHeart(p,world.State);Assert(world.State.Items.Count(i=>i.Id==AdventureRules.Heart)==1);});
Test("training charges silver per tenth and stops at teacher's one-third ceiling",()=>{Npc("npc.sera");int marks=InventoryRules.Marks(world.State);Good("train","npc.sera","magery","",100);Assert(AdventureRules.Skill(world.State,"magery").Value==333&&InventoryRules.Marks(world.State)==marks-33);Bad("train","npc.sera","magery","",10);});
Test("wrong teacher, range, locks and insufficient funds reject atomically",()=>{Npc("npc.sera");Bad("train","npc.sera","swords","",10);Good("skill-lock","","magery","locked");Bad("train","npc.sera","magery","",10);Good("skill-lock","","magery","up");world.State.Items.RemoveAll(i=>i.Definition==InventoryRules.Currency);Bad("train","npc.sera","magery","",10);});
Test("skill cap uses a decrease-locked donor rather than exceeding 700.0",()=>{var a=world.State.Adventure;foreach(var k in a.Skills)k.Value=600;for(int i=0;i<4;i++)a.Skills[i].Value=700;var target=AdventureRules.Skill(world.State,"magery");Assert(a.Skills.Sum(k=>k.Value)==7000);Assert(!ProgressionSimulation.MakeRoom(world.State,target,1));a.Skills[0].Lock="down";Assert(ProgressionSimulation.MakeRoom(world.State,target,1));target.Value++;Assert(a.Skills.Sum(k=>k.Value)==7000&&a.Skills[0].Value==699);});
Test("use-based fractional gains stop when locked",()=>{var k=AdventureRules.Skill(world.State,"swords");k.Value=1;for(int i=0;i<8;i++)ProgressionSimulation.Check(world.State,"swords",.5);Assert(k.Value>1&&k.Value<=33);k.Lock="locked";int value=k.Value;for(int i=0;i<20;i++)ProgressionSimulation.Check(world.State,"swords",.5);Assert(k.Value==value);});
Test("saved random state reproduces checks instead of rerolling after reload",()=>{uint seed=world.State.Adventure.RandomState;double first=ProgressionSimulation.Roll(world.State);world.State.Adventure.RandomState=seed;Assert(first==ProgressionSimulation.Roll(world.State));});
Test("bandage use consumes once, persists its timer and resolves after its delay",()=>{world.State.Combat.Health=40;AdventureRules.Skill(world.State,"healing").Value=1000;AdventureRules.Skill(world.State,"anatomy").Value=1000;int qty=world.State.Items.Where(i=>i.Definition.EndsWith("bandage")).Sum(i=>i.Amount);Good("bandage");Assert(world.State.Adventure.BandageAt==8&&world.State.Items.Where(i=>i.Definition.EndsWith("bandage")).Sum(i=>i.Amount)==qty-1);Bad("bandage");Tick(8.1);Assert(world.State.Combat.Health>40&&world.State.Adventure.BandageAt==0);});
Test("moving beyond bandage reach cancels the pending healing",()=>{world.State.Combat.Health=30;Good("bandage");At(world.State.X+2,world.State.Y);Tick(.1);Assert(world.State.Adventure.BandageAt==0);});
Test("meditation requires free hands and ends on movement",()=>{world.State.Combat.Mana=40;Bad("meditate");foreach(var i in world.State.Items.Where(i=>i.Where=="equipped"&&p.Definitions.Items.First(d=>d.Id==i.Definition).Equipment!.Slot is "sword" or "shield")){i.Where="bag";i.X=160;i.Y=280;}AdventureRules.Skill(world.State,"meditation").Value=1000;Good("meditate");Assert(world.State.Adventure.Meditating);Tick(2);Assert(world.State.Combat.Mana>40);var r=world.Handle(new(){Type="step",Dx=1,Dy=0});Assert(r.Ok&&!world.State.Adventure.Meditating);});
Test("NPCs walk collision-valid tiles and pause near a speaker",()=>{At(20,120);var npc=AdventureRules.Npc(world.State,"npc.tomas")!;int x=npc.X,y=npc.Y;Tick(12);Assert(npc.X!=x||npc.Y!=y);Assert(p.CanStand(p.Map,npc.X,npc.Y));At(npc.X,npc.Y);Good("interact",npc.Id);x=npc.X;y=npc.Y;Tick(2);Assert(npc.X==x&&npc.Y==y);});
Test("world clock and NPC schedule targets follow five-second UO minutes",()=>{Assert(AdventureRules.Clock(world.State)=="08:00");world.State.ElapsedSeconds=3600;Assert(AdventureRules.Clock(world.State)=="20:00");TownSimulation.Advance(p,world.State);Assert(world.State.Adventure.Npcs.Any(n=>n.Activity is "walking" or "socializing"));});
Test("vendor restocks on campaign time while pause freezes it",()=>{var stock=world.State.MerchantStock[0];stock.Amount=0;world.State.ElapsedSeconds=3600;world.State.Paused=true;AdventureSimulation.Advance(p,world.State,0);Assert(stock.Amount==0);world.State.Paused=false;AdventureSimulation.Advance(p,world.State,0);Assert(stock.Amount==20&&world.State.Adventure.NextRestockAt==7200);});
Test("ghosts can walk and a nearby healer restores life without returning equipment",()=>{world.State.Combat.Health=0;world.State.Combat.Dead=true;world.State.Combat.WarMode=false;Npc("npc.elin");var r=world.Handle(new(){Type="step",Dx=1,Dy=0});Assert(r.Ok);Good("resurrect","npc.elin");Assert(!world.State.Combat.Dead&&world.State.Combat.Health==10);});
Test("full backpack places physical rewards on the ground like ServUO",()=>{ReadyMain();while(world.State.Items.Count(i=>i.Where=="bag")<125)world.State.Items.Add(new(){Id="filler."+world.State.Items.Count,Definition=InventoryRules.Currency,Amount=1,X=100,Y=180});Good("quest-claim","quest.beacon");Assert(world.State.Items.Any(i=>i.Definition.EndsWith("greatblade")&&i.Where=="ground"));});
Test("global item exhaustion keeps quest and rewards unchanged for a later claim",()=>{ReadyMain();world.State.Items.First(i=>i.Definition==InventoryRules.Currency).Where="ground";world.State.Items.First(i=>i.Definition==InventoryRules.Currency).X=world.State.X;world.State.Items.First(i=>i.Definition==InventoryRules.Currency).Y=world.State.Y;while(world.State.Items.Count<512)world.State.Items.Add(new(){Id="filler."+world.State.Items.Count,Definition=InventoryRules.Currency,Where="ground",X=world.State.X,Y=world.State.Y});Bad("quest-claim","quest.beacon");Assert(Q("quest.beacon").Status=="ready");});
Test("complete adventure state and marked inventory round-trip through save validation",()=>{Npc("npc.orrin");Good("quest-accept","quest.forge");Good("quest-mark","quest.forge");var save=new CampaignSave{Fingerprint=p.Fingerprint,MapHash=p.MapHash,Map=p.Map.Clone(),State=JsonSerializer.Deserialize<SessionState>(Wire.Encode(world.State),ContentPackage.Json)!};CampaignStore.Validate(p,save);world.Restore(save);Assert(Q("quest.forge").Status=="ready"&&world.State.Items.Any(i=>i.QuestId=="quest.forge")&&world.State.Paused);});
Test("malformed saved quest counts and skill locks reject explicitly",()=>{var s=JsonSerializer.Deserialize<SessionState>(Wire.Encode(world.State),ContentPackage.Json)!;s.Adventure.Quests[0].Counts[0]=int.MaxValue;try{AdventureRules.Validate(p,s);throw new Exception("accepted bad objective");}catch(ContentException){}s=JsonSerializer.Deserialize<SessionState>(Wire.Encode(world.State),ContentPackage.Json)!;s.Adventure.Skills[0].Lock="cheat";try{AdventureRules.Validate(p,s);throw new Exception("accepted bad lock");}catch(ContentException){}});
Test("live throwing uses the Throwing skill and consumes one ordinary crystal",()=>{var e=world.State.Combat.Enemies.First(e=>e.Id=="encounter.woods.hound1");At(e.X-2,e.Y);int quantity=world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal")&&InventoryRules.Carried(world.State,i)).Sum(i=>i.Amount);Good("throw",e.Id);Assert(AdventureRules.Skill(world.State,"throwing").Uses==1&&world.State.Items.Where(i=>i.Definition.EndsWith("tide-crystal")&&InventoryRules.Carried(world.State,i)).Sum(i=>i.Amount)==quantity-1);});
Test("strength and intelligence improve their matching damage without changing fixture rules",()=>{int weapon=ProgressionSimulation.Damage(world.State,12),spell=ProgressionSimulation.MagicDamage(world.State,18);world.State.Adventure.Strength=80;world.State.Adventure.Intelligence=80;Assert(ProgressionSimulation.Damage(world.State,12)>weapon&&ProgressionSimulation.MagicDamage(world.State,18)>spell);world.State.Adventure.Enabled=false;Assert(ProgressionSimulation.Damage(world.State,12)==12&&ProgressionSimulation.MagicDamage(world.State,18)==18);world.State.Adventure.Enabled=true;});
Console.WriteLine($"{count} quest, town and progression checks passed.");
